// The walls of a footprint that face the viewer, each with its daylight factor (1 = full sun).
function walls(E,cs){const n=cs.length;let cx=0,cy=0;for(const p of cs){cx+=p.x/n;cy+=p.y/n;}const out=[];for(let i=0;i<n;i++){const p=cs[i],q=cs[(i+1)%n],d=mul(E.L,{x:(p.x+q.x)/2-cx,y:(p.y+q.y)/2-cy});if(d.y>1)out.push({i,p,q,f:.8-.18*d.x/Math.hypot(d.x,d.y)});}return out;}
function hull(ps){ps=[...ps].sort((a,b)=>a.x-b.x||a.y-b.y);const cr=(o,a,b)=>(a.x-o.x)*(b.y-o.y)-(a.y-o.y)*(b.x-o.x),lo=[],hi=[];for(const p of ps){while(lo.length>1&&cr(lo[lo.length-2],lo[lo.length-1],p)<=0)lo.pop();lo.push(p);}for(let i=ps.length-1;i>=0;i--){const p=ps[i];while(hi.length>1&&cr(hi[hi.length-2],hi[hi.length-1],p)<=0)hi.pop();hi.push(p);}return lo.slice(0,-1).concat(hi.slice(0,-1));}
