   for(let i=Math.floor(q[0]/C),i1=Math.floor(q[2]/C),j0=Math.floor(q[1]/C),j1=Math.floor(q[3]/C);i<=i1;i++)for(let j=j0;j<=j1;j++){const list=grid.get(i*65536+j);if(list)for(let n=0;n<list.length;n++){const u=list[n];if(u.stamp===id)continue;u.stamp=id;const rb=u.rb;if(rb[0]<q[2]&&rb[2]>q[0]&&rb[1]<q[3]&&rb[3]>q[1]&&u!==t.parent&&u.parent!==t)cand.push(u);}}
