 const ps=[];for(const X of [-1300,front+300])for(const Y of [-450,w+450])for(const z of [0,zb+300])ps.push(S(add({x:X,y:Y},E.up(z))));
 const minX=Math.min(...ps.map(p=>p.x))-250,maxX=Math.max(...ps.map(p=>p.x))+250,minY=Math.min(...ps.map(p=>p.y))-420,maxY=Math.max(...ps.map(p=>p.y))+250;
