 s+='<path d="M-1180 -780H500L'+o(500,-780)+'H'+(-1180+D.x)+'Z" fill="#ffd24a" stroke="#8a5f12" stroke-width="30" stroke-linejoin="round"/><path d="M-1180 -780H500V-180H-1180Z" fill="#f0ae1f" stroke="#8a5f12" stroke-width="30" stroke-linejoin="round"/><path d="M-1260 -900H-700V-150H-1260Z" fill="#3b4246" stroke="#1d2123" stroke-width="30"/><path d="M-1260 -900L'+o(-1260,-900)+'H'+(-700+D.x)+'L-700 -900Z" fill="#555e63"/>';
 s+='<path d="M-900 -300a260 260 0 1 0 1 0zM250 -320a290 290 0 1 0 1 0z" fill="#1d2123"/><path d="M-900 -140a90 90 0 1 0 1 0zM250 -150a100 100 0 1 0 1 0z" fill="#c3cacd"/>';
 s+=driver?'<path d="M-380 -1150V-760" stroke="#27364a" stroke-width="150"/><rect x="-560" y="-1500" width="330" height="480" rx="110" fill="#d7f02f" stroke="#7d8a16" stroke-width="25"/><path d="M-560 -1180H-230" stroke="#eef3f5" stroke-width="40"/><circle cx="-395" cy="-1640" r="125" fill="#e2b48a"/><path d="M-545 -1660Q-545 -1830 -395 -1830Q-245 -1830 -245 -1660Z" fill="#ffd02a" stroke="#b58b12" stroke-width="20"/>':'<path d="M-560 -1000H-250V-780H-560Z" fill="#23292b"/>';
