 if(load&&load.type!==undefined){const cage=load.type==='CAGE',ok=load.condition!=='DAMAGED'&&load.condition!=='UNSERVICEABLE',rim=ok?(cage?STATUS_COLOURS.cage:STATUS_COLOURS.stillage):STATUS_COLOURS.damaged,x0=760,x1=1850,z=-160,h=780,side=cage?'#d8ab2b':'#a8b2b5';
  s+='<path d="M'+x0+' '+z+'H'+x1+'V'+(z-h)+'H'+x0+'Z" fill="'+side+'" stroke="#34403b" stroke-width="30"/><path d="M'+x1+' '+z+'L'+o(x1,z)+'V'+(z-h+D.y)+'L'+x1+' '+(z-h)+'Z" fill="'+shade(side,.75)+'" stroke="#34403b" stroke-width="30"/><path d="M'+x0+' '+(z-h)+'H'+x1+'L'+o(x1,z-h)+'H'+(x0+D.x)+'Z" fill="#39413d" stroke="'+rim+'" stroke-width="70"/><path d="M'+x0+' '+z+'V'+(z-h)+'M'+x1+' '+z+'V'+(z-h)+'M'+x0+' '+(z-h/2)+'H'+x1+'" stroke="'+rim+'" stroke-width="60"/>';}
